struct stat sb;
int dirfd = AT_FDCWD; // Search relative to CWD
const char *path = "path/to/file";
int flags = AT_SYMLINK_NOFOLLOW; // or 0 to follow links

// Use AT_FDCWD for standard stat() behavior
// Retrieve status without following symlinks
int result = fstatat(dirfd, path, &sb, flags);

if (result == 0) {
    // Status retrieved successfully
    // sb.st_mode, sb.st_size, etc. available
} else {
    // Error: file not found (errno set)
}
